import type { LiveOptions } from '@inertiajs/core'
import { echoLive, type EchoOptions } from '@inertiajs/core/echo'
import { echo as resolveEcho, echoIsConfigured } from '@laravel/echo-vue'

export type { EchoOptions }

/** Delivers live prop updates over the Echo instance `configureEcho()` from `@laravel/echo-vue` set up. */
export const echo = (options: EchoOptions = {}): LiveOptions =>
  echoLive({ echo: resolveEcho, echoIsConfigured }, options)
